begin;
-- =============================================================================
--  Lagon Arena, inverse de la migration 0003 (après l'import du Panthéon)
--  Projet Supabase cukahpyqkljiddmimpyi (« Babash - applications »)
--  Nom de migration : lagon_0003_pantheon_importe_inverse
-- =============================================================================
--  Ce qu'il fait : la colonne id de lagon.pantheon redevient « generated by
--  default », pour pouvoir refaire un import qui garde ses identifiants.
--
--  Ce qu'il ne fait pas :
--   - il ne retire pas les tortues importées. Pour refaire l'import depuis le
--     début : delete from lagon.pantheon; dans l'éditeur SQL, avant la
--     bascule de la page (après, cela effacerait aussi les nouvelles tortues) ;
--   - il ne remet pas les textes vides de l'import (ils n'avaient pas de sens) ;
--   - il laisse le compteur des identifiants où il est : c'est sans risque.
-- =============================================================================

do $$
begin
  if current_user <> 'postgres' then
    raise exception 'À lancer en postgres (éditeur SQL de Supabase ou apply_migration), pas en % : arrêt, rien n''a été modifié.', current_user;
  end if;
  if to_regclass('lagon.pantheon') is null
     or coalesce(obj_description(to_regclass('lagon.pantheon'), 'pg_class'), '') not like 'Lagon Arena.%' then
    raise exception 'La table lagon.pantheon de la migration 0002 manque : rien à défaire. Arrêt, rien n''a été modifié.';
  end if;
end $$;

alter table lagon.pantheon alter column id set generated by default;

commit;
